        [Test]
        public void AnalyzeOnlyPreservesBytesMetadataAndCreatesNoBackup()
        {
            string path = Prefab();
            File.WriteAllBytes(path, new UTF8Encoding(true).GetPreamble().Concat(Encoding.UTF8.GetBytes(
                File.ReadAllText(path).Replace("\n", "\r\n"))).ToArray());
            byte[] before = File.ReadAllBytes(path);
            byte[] metadata = File.ReadAllBytes(path + ".meta");
            string backupRoot = "UserSettings/UnityBox/AdvancedCostumeController/ComponentReferenceMigration";
            string[] existing = Directory.Exists(backupRoot) ? Directory.GetFiles(backupRoot, "*", SearchOption.AllDirectories) : Array.Empty<string>();
            var plan = MigrationEngine.Scan(new[] { path });
            Assert.That(plan.Entries.Single().TypeName, Is.EqualTo(Primary));
            Assert.That(plan.Entries.Single().Status, Is.EqualTo(plan.TargetTypes.Single(target => target.TypeName == Primary).Available
                ? MigrationStatus.Ready : MigrationStatus.Unavailable));
            Assert.That(File.ReadAllBytes(path), Is.EqualTo(before));
            Assert.That(File.ReadAllBytes(path + ".meta"), Is.EqualTo(metadata));
            Assert.That(Directory.Exists(backupRoot) ? Directory.GetFiles(backupRoot, "*", SearchOption.AllDirectories) : Array.Empty<string>(), Is.EqualTo(existing));
        }

