        [Test]
        public void ExplicitBatchPreservesEveryByteExceptSelectedScriptGuidAndBacksUpOriginal()
        {
            string path = Prefab(PrimaryFields + "  userNote: " + Legacy + "\n");
            string text = File.ReadAllText(path)
                .Replace("  m_Script:", "  # 中文名称与 emoji 🙂 位于脚本 GUID 之前\n  m_Script:")
                .Replace("\n", "\r\n");
            byte[] original = Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(text)).ToArray();
            File.WriteAllBytes(path, original);
            byte[] metadata = File.ReadAllBytes(path + ".meta");
            var plan = MigrationEngine.Scan(new[] { path });
            var entry = plan.Entries.Single();
            Assert.That(entry.Status, Is.EqualTo(MigrationStatus.Ready));
            var result = MigrationEngine.Apply(plan);
            Assert.That(result.RepairedComponents, Is.EqualTo(1));
            Assert.That(result.ChangedAssets, Is.EqualTo(new[] { path }));
            string expected = text.Replace("m_Script: {fileID: 11500000, guid: " + Legacy,
                "m_Script: {fileID: 11500000, guid: " + entry.TargetGuid);
            Assert.That(File.ReadAllBytes(path), Is.EqualTo(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(expected)).ToArray()));
            Assert.That(File.ReadAllBytes(path + ".meta"), Is.EqualTo(metadata));
            Assert.That(File.ReadAllBytes(Path.Combine(result.BackupDirectory, path)), Is.EqualTo(original));
            Assert.That(File.ReadAllBytes(Path.Combine(result.BackupDirectory, path + ".meta")), Is.EqualTo(metadata));
            Assert.That(File.Exists(Path.Combine(result.BackupDirectory, "report.json")), Is.True);
            Assert.That(MigrationEngine.Apply(MigrationEngine.Scan(new[] { path })).RepairedComponents, Is.Zero);
        }

